// OpenRouter TTS — via chat completions + audio modality (SSE stream)
import { PROVIDER_MEDIA } from "../../providers/index.js";

const TTS_CFG = PROVIDER_MEDIA["openrouter"]?.ttsConfig || {};

export default {
  async synthesize(text, model, credentials) {
    if (!credentials?.apiKey) throw new Error("No OpenRouter API key configured");

    // model format: "tts-model/voice" e.g. "openai/gpt-4o-mini-tts/alloy"
    let ttsModel = TTS_CFG.defaultModel;
    let voice = "alloy";
    if (model && model.includes("/")) {
      const lastSlash = model.lastIndexOf("/");
      const maybVoice = model.slice(lastSlash + 1);
      const maybeModel = model.slice(0, lastSlash);
      if (maybeModel.includes("/")) {
        ttsModel = maybeModel;
        voice = maybVoice;
      } else {
        voice = model;
      }
    } else if (model) {
      voice = model;
    }

    const res = await fetch(TTS_CFG.baseUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${credentials.apiKey}`,
        ...(TTS_CFG.headers || {}),
      },
      body: JSON.stringify({
        model: ttsModel,
        modalities: ["text", "audio"],
        audio: { voice, format: "wav" },
        stream: true,
        messages: [{ role: "user", content: text }],
      }),
    });

    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err?.error?.message || `OpenRouter TTS failed: ${res.status}`);
    }

    // Parse SSE stream, accumulate base64 audio chunks
    const chunks = [];
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split("\n");
      buffer = lines.pop();
      for (const line of lines) {
        if (!line.startsWith("data: ") || line === "data: [DONE]") continue;
        try {
          const json = JSON.parse(line.slice(6));
          const audioData = json.choices?.[0]?.delta?.audio?.data;
          if (audioData) chunks.push(audioData);
        } catch {}
      }
    }

    if (chunks.length === 0) throw new Error("OpenRouter TTS returned no audio data");
    return { base64: chunks.join(""), format: "wav" };
  },
};

// Self-hosted OpenAI-compatible TTS — POST {baseUrl}/v1/audio/speech.
//
// A SPECIAL_ADAPTER rather than a genericFormats handler on purpose: the generic
// dispatcher resolves baseUrl from the static registry entry
// (`synthesizeViaConfig` reads `cfg.baseUrl`) and never looks at the connection,
// which is exactly the limitation this provider exists to lift.
import { Buffer } from "node:buffer";

const DEFAULT_BASE_URL = "http://localhost:8880";
const DEFAULT_MODEL = "kokoro";
const DEFAULT_VOICE = "af_heart";

export default {
  async synthesize(text, model, credentials, responseFormat = "mp3") {
    // Accept either providerSpecificData.baseUrl (how the custom embedding and
    // STT providers carry it) or a bare credentials.baseUrl (how the OpenAI TTS
    // adapter does), so a connection configured either way works.
    const raw = credentials?.providerSpecificData?.baseUrl || credentials?.baseUrl || DEFAULT_BASE_URL;
    // Tolerate a baseUrl given as the full endpoint or with a trailing /v1 —
    // both are natural things to paste, and silently double-appending the path
    // would 404 with nothing pointing at the cause.
    const base = String(raw)
      .replace(/\/+$/, "")
      .replace(/\/v1\/audio\/speech$/, "")
      .replace(/\/v1$/, "");

    // The provider prefix is already stripped by getModelInfo, so `model` here is
    // "kokoro" or "kokoro/af_heart" — NOT "selfhosted-tts/...".
    //
    // A bare value is the MODEL, not the voice. The OpenAI adapter reads a bare
    // value as a voice, which is right for a service whose model is fixed
    // ("tts-1") and whose voice varies — but wrong here, where the model is the
    // variable part. Treating it as a voice sent voice="kokoro" upstream and
    // Kokoro answered 400, so `selfhosted-tts/kokoro` — the obvious way to
    // address this provider — was the one form that did not work (verified
    // against a live Kokoro through 9router, 2026-08-03).
    let ttsModel = DEFAULT_MODEL;
    let voice = DEFAULT_VOICE;
    if (model) {
      const parts = String(model).split("/").filter(Boolean);
      if (parts.length >= 2) {
        ttsModel = parts[0];
        voice = parts.slice(1).join("/");
      } else if (parts.length === 1) {
        ttsModel = parts[0];
      }
    }

    const res = await fetch(`${base}/v1/audio/speech`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(credentials?.apiKey ? { Authorization: `Bearer ${credentials.apiKey}` } : {}),
      },
      body: JSON.stringify({
        model: ttsModel,
        voice,
        input: text,
        response_format: responseFormat,
      }),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err?.error?.message || `Self-hosted TTS failed: ${res.status}`);
    }
    const buf = await res.arrayBuffer();
    return { base64: Buffer.from(buf).toString("base64"), format: responseFormat };
  },
};

// Xiaomi MiMo TTS — via OpenAI-compatible chat completions (non-streaming).
// Docs: https://mimo.mi.com/docs/zh-CN/quick-start/usage-guide/audio/speech-synthesis-v2.5
// Message contract: target text in `role: assistant` content, style/voice
// instructions in `role: user` content. Voice is selected via the top-level
// `audio.voice` field (NOT embedded in the model name).
import { parseModelVoice } from "./_base.js";

const DEFAULT_MODEL = "mimo-v2.5-tts";
const DEFAULT_VOICE = "mimo_default";

export default {
  synthesize(text, model, credentials, responseFormat, { style, language } = {}) {
    if (!credentials?.apiKey) throw new Error("xiaomi-mimo API key required");
    return synthesizeMiMo(text, model, credentials.apiKey, style, language);
  },
};

export async function synthesizeMiMo(text, model, apiKey, style, language) {
  const { modelId, voiceId } = parseModelVoice(model, DEFAULT_MODEL, DEFAULT_VOICE, [DEFAULT_MODEL]);

  // Language and style are soft instructions → prepend as a role:user message.
  // MiMo auto-detects the spoken language of the text; the hint only nudges it
  // (e.g. "Speak in English.") and is independent of the chosen voice.
  const instructions = [];
  if (language) instructions.push(`Speak in ${language}.`);
  if (style) instructions.push(style);

  const messages = [{ role: "assistant", content: text }];
  if (instructions.length) messages.unshift({ role: "user", content: instructions.join(" ") });

  const res = await fetch("https://api.xiaomimimo.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: modelId,
      stream: false,
      messages,
      audio: {
        format: "wav",
        voice: voiceId || DEFAULT_VOICE,
      },
    }),
  });

  const rawText = await res.text();
  let data = {};
  if (rawText) {
    try { data = JSON.parse(rawText); } catch { data = {}; }
  }

  if (!res.ok) {
    throw new Error(data?.error?.message || rawText || `MiMo TTS error (${res.status})`);
  }

  const audio = data?.choices?.[0]?.message?.audio?.data;
  if (!audio) throw new Error(data?.error?.message || "MiMo TTS returned no audio");

  return {
    base64: audio,
    format: data?.choices?.[0]?.message?.audio?.format || "wav",
  };
}

// OpenRouter video jobs — https://openrouter.ai/docs/api/api-reference/videos
//
// Same async shape as xAI (POST → { id, status }, GET → status/unsigned_urls),
// two differences only: creation POSTs to the collection root (no `/generations`
// suffix) and the account headers come from the registry entry.
// Response bodies are passed through verbatim.

// ponytail: generations only — OpenRouter has no edits/extensions endpoint today.
const SUPPORTED_ACTIONS = new Set(["generations"]);

function headers(config, token) {
  return {
    Accept: "application/json",
    ...(config.headers || {}),
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };
}

export default {
  buildRequest({ config, action, requestId, rawBody, contentType, token }) {
    const base = config.baseUrl.replace(/\/$/, "");

    if (requestId) {
      return { method: "GET", url: `${base}/${encodeURIComponent(requestId)}`, headers: headers(config, token) };
    }
    if (!SUPPORTED_ACTIONS.has(action)) {
      return { error: `OpenRouter video supports 'generations' only (got '${action}')` };
    }
    if (contentType && !contentType.includes("application/json")) {
      return { error: "OpenRouter video requires an application/json body" };
    }
    return {
      method: "POST",
      url: base,
      headers: { ...headers(config, token), "Content-Type": "application/json" },
      body: rawBody,
    };
  },
};

// Vertex AI (Veo) video jobs.
//
// Vertex does NOT speak the OpenAI-ish /v1/videos shape, so unlike OpenRouter
// this adapter translates both directions:
//   create → POST {model}:predictLongRunning  { instances[], parameters{} } → { name }
//   poll   → POST {model}:fetchPredictOperation { operationName } → { done, response }
// Docs: https://cloud.google.com/vertex-ai/generative-ai/docs/model-reference/veo-video-generation
//
// The operation name is a resource path (contains "/"), so it is base64url-encoded
// into the job id returned to the client — GET /v1/videos/{id} stays a flat path.
import { parseVertexSaJson, refreshVertexToken } from "../../services/tokenRefresh.js";

const DEFAULT_LOCATION = "us-central1";

const encodeJobId = (name) => Buffer.from(name, "utf8").toString("base64url");

// Operation name shape: projects/{p}/locations/{l}/publishers/{pub}/models/{m}/operations/{op}.
// Anchored and single-segment-per-field so a decoded path can never carry `..` or a
// host-changing prefix into the request URL.
const OPERATION_NAME_RE = /^projects\/[^/]+\/locations\/[^/]+\/publishers\/[^/]+\/models\/[^/]+\/operations\/[^/]+$/;

function modelPathOf(operationName) {
  return operationName.slice(0, operationName.indexOf("/operations/"));
}

function decodeJobId(id) {
  const raw = String(id ?? "");
  // Buffer.from(x, "base64url") silently drops invalid characters instead of
  // throwing, so only ids that re-encode byte-for-byte are accepted.
  if (!raw || raw.length > 1024 || !/^[A-Za-z0-9_-]+$/.test(raw)) return null;
  const decoded = Buffer.from(raw, "base64url").toString("utf8");
  if (Buffer.from(decoded, "utf8").toString("base64url") !== raw) return null;
  return OPERATION_NAME_RE.test(decoded) ? decoded : null;
}

async function resolveAuth(credentials, log) {
  const saJson = parseVertexSaJson(credentials?.apiKey);
  const projectId =
    saJson?.project_id ||
    credentials?.projectId ||
    credentials?.providerSpecificData?.projectId;
  const location = credentials?.providerSpecificData?.location || DEFAULT_LOCATION;

  if (!projectId) {
    return { error: "Vertex video requires a project_id — use Service Account JSON or set providerSpecificData.projectId" };
  }

  let token = credentials?.accessToken;
  if (saJson) {
    const minted = await refreshVertexToken(saJson, log);
    if (!minted?.accessToken) return { error: "Vertex video: failed to mint access token from service account JSON" };
    token = minted.accessToken;
  }
  if (!token) return { error: "Vertex video requires Service Account JSON or an OAuth access token (raw API keys are not supported)" };

  return { token, projectId, location };
}

/** OpenAI-ish video body → Vertex predictLongRunning body. */
function toVertexBody(body) {
  const instance = { prompt: body.prompt };
  // Image-to-video: accept the Vertex-native shape or a bare data URL / base64 string.
  const image = body.image ?? body.image_url;
  if (image && typeof image === "object") {
    instance.image = image;
  } else if (typeof image === "string") {
    const match = image.match(/^data:([^;]+);base64,(.*)$/s);
    instance.image = match
      ? { bytesBase64Encoded: match[2], mimeType: match[1] }
      : { gcsUri: image };
  }
  if (body.video && typeof body.video === "object") instance.video = body.video;

  const parameters = {};
  if (body.n != null) parameters.sampleCount = Number(body.n);
  if (body.duration != null) parameters.durationSeconds = Number(body.duration);
  if (body.aspect_ratio) parameters.aspectRatio = body.aspect_ratio;
  if (body.resolution) parameters.resolution = body.resolution;
  if (body.seed != null) parameters.seed = body.seed;
  if (body.negative_prompt) parameters.negativePrompt = body.negative_prompt;
  // Without storageUri Vertex returns inline base64 bytes; a GCS bucket keeps
  // the poll response small and is what production callers want.
  if (body.storage_uri) parameters.storageUri = body.storage_uri;
  if (body.generate_audio != null) parameters.generateAudio = !!body.generate_audio;

  return { instances: [instance], ...(Object.keys(parameters).length ? { parameters } : {}) };
}

/** Vertex operation → the async-job shape 9Router clients already poll for. */
function fromVertexOperation(json) {
  if (!json?.name) return json;
  const id = encodeJobId(json.name);
  if (json.error) {
    return { id, request_id: id, status: "failed", error: json.error };
  }
  if (!json.done) {
    return { id, request_id: id, status: "pending" };
  }
  const samples =
    json.response?.videos ||
    json.response?.generateVideoResponse?.generatedSamples ||
    [];
  const videos = samples.map((s) => ({
    url: s.gcsUri || s.video?.uri || s.uri || null,
    b64_json: s.bytesBase64Encoded || s.video?.bytesBase64Encoded || null,
    mime_type: s.mimeType || s.video?.mimeType || "video/mp4",
  }));
  return { id, request_id: id, status: "completed", video: videos[0] || null, videos };
}

export default {
  async buildRequest({ config, action, requestId, rawBody, contentType, credentials, log }) {
    if (contentType && !contentType.includes("application/json")) {
      return { error: "Vertex video requires an application/json body" };
    }

    const auth = await resolveAuth(credentials, log);
    if (auth.error) return { error: auth.error };
    const { token, projectId, location } = auth;
    const base = (config.baseUrl || "https://aiplatform.googleapis.com").replace(/\/$/, "");
    const headers = { Accept: "application/json", "Content-Type": "application/json", Authorization: `Bearer ${token}` };

    if (requestId) {
      const operationName = decodeJobId(requestId);
      if (!operationName) return { error: "Invalid Vertex video job id" };
      return {
        method: "POST",
        url: `${base}/v1/${modelPathOf(operationName)}:fetchPredictOperation`,
        headers,
        body: JSON.stringify({ operationName }),
      };
    }

    if (action !== "generations") {
      // ponytail: Veo extend/edit go through generations with `video`/`image` in the body.
      return { error: `Vertex video supports 'generations' only (got '${action}')` };
    }

    let body;
    try {
      body = JSON.parse(typeof rawBody === "string" ? rawBody : rawBody.toString("utf8"));
    } catch {
      return { error: "Invalid JSON body" };
    }
    if (!body.model) return { error: "Vertex video requires a model (e.g. vertex/veo-3.1-generate-preview)" };
    // Plain model id only — a path segment carrying "/" or ".." would rewrite the URL.
    if (!/^[A-Za-z0-9._-]+$/.test(body.model)) return { error: "Invalid Vertex video model id" };
    if (!body.prompt && !body.image && !body.image_url) return { error: "Vertex video requires a prompt or an image" };

    return {
      method: "POST",
      url: `${base}/v1/projects/${projectId}/locations/${location}/publishers/google/models/${body.model}:predictLongRunning`,
      headers,
      body: JSON.stringify(toVertexBody(body)),
    };
  },

  transformResponse: fromVertexOperation,
};

