function Section({ title, icon, kind, providers, connections, combos, onCreateCombo }) {
  return (
    <div>
      {/* Header — title left, Create Combo right */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-3">
